document.addEventListener("DOMContentLoaded",function(){const urlParams=new URLSearchParams(window.location.search);const afidParam=urlParams.get('afid');const variantParam=urlParams.get('variant');const funnelId=document.body.dataset.funnel;const bodyClassList=document.body.classList;const pageTypes={cartpanda:bodyClassList.contains('cartpanda'),clickbank:bodyClassList.contains('clickbank'),digistore24:bodyClassList.contains('digistore24')};const buylinks=Array.from(document.querySelectorAll('.buylink'));const copyb=document.querySelectorAll("#copyb");const copyw=document.querySelectorAll("#copyw");const hiddenContent=document.querySelectorAll(".esconder");const validKits=['kit1','kit2','kit3'];const allKitIds=['k1','k2','k3'];let trackerParam=pageTypes.digistore24?"custom":"campaignkey";const trackerValue=urlParams.get(trackerParam);const isFrontBlack=['vsl','dtc','ecom'].includes(document.body.id);const hasCopyBlack=(urlParams.get(trackerParam)?.includes('cyb'))||afidParam;function renderKitVisual(kit){const kitId=`k${kit.slice(-1)}`;allKitIds.forEach(id=>{const elements=document.querySelectorAll(`[id="${ id }"]`);elements.forEach(el=>{if(id===kitId){el.style.display='block'}else{el.remove()}})})}function applyLegacyParamsToTracker(){const legacyKeys=['pg','kit','funnelid'];const legacyParams=legacyKeys.map(key=>({key,value:urlParams.get(key)})).filter(param=>param.value);if(!legacyParams.length){return false}buylinks.forEach(link=>{const url=new URL(link.href,window.location.origin);let currentValue=url.searchParams.get(trackerParam)||"";let parts=currentValue?currentValue.split('--'):[];legacyParams.forEach(({key,value})=>{const formatted=`${ key }-${ value }`;if(!parts.includes(formatted)){parts.push(formatted)}});url.searchParams.set(trackerParam,parts.join('--'));link.href=url.toString()});const kitValue=urlParams.get('kit');const validKits=['kit1','kit2','kit3'];let activeKit='kit3';if(kitValue&&validKits.includes(kitValue)){activeKit=kitValue}renderKitVisual(activeKit);return true}function showCopyBlack(){copyb.forEach(e=>e.style.display="block");copyw.forEach(e=>e.style.display="none");hiddenContent.forEach(e=>e.style.display="none")}function removeCopyBlack(){copyb.forEach(e=>e.remove())}function setKitOnBuylinks(){buylinks.forEach(link=>{const kitClass=validKits.find(kit=>link.classList.contains(kit));if(kitClass){const kitValue=`kit-${ kitClass }`;const url=new URL(link.href,window.location.origin);appendTrackerValueToParam(url,trackerParam,kitValue);link.href=url.toString()}})}function renderKitSection(){if(!allKitIds.some(id=>document.getElementById(id))){return}let activeKit='kit3';let shouldInjectCampaignKey=false;let generatedCampaignKey='';if(trackerValue?.includes('kit-')){const kitMatch=trackerValue.split('--').find(part=>part.startsWith('kit-'));const kitKey=kitMatch?.split('-')[1];if(validKits.includes(kitKey)){activeKit=kitKey }}else if(variantParam&&typeof variantToKitMap==='object'){for(const[kit,ids]of Object.entries(variantToKitMap)){if(ids.includes(variantParam)){activeKit=kit;shouldInjectCampaignKey=!urlParams.has('campaignkey');if(shouldInjectCampaignKey){generatedCampaignKey=`kit-${ kit }--funnelid-checkout--pg-cyb`}break}}}renderKitVisual(activeKit);buylinks.forEach(link=>{const url=new URL(link.href,window.location.origin);if(shouldInjectCampaignKey){url.searchParams.set('campaignkey',generatedCampaignKey)}const currentTrackerValue=url.searchParams.get(trackerParam)||'';const kitTag=`kit-${ activeKit }`;if(!currentTrackerValue.includes('kit-')){const newTrackerValue=currentTrackerValue?`${ currentTrackerValue }--${ kitTag }`:kitTag;url.searchParams.set(trackerParam,newTrackerValue)}link.href=url.toString()})}function setFunnelIdOnBuyLinks(){const trackerHasFunnelId=trackerValue?.toLowerCase().includes('funnelid-');if(trackerHasFunnelId){return}let funnelValue=null;if(variantParam){funnelValue='checkout'}else if(funnelId){if(funnelId.includes('-')){console.error(`Invalid data-funnel value: '${ funnelId }' cannot contain hyphens (-).`);return}funnelValue=funnelId}if(!funnelValue){return}const funnelPair=`funnelid-${ funnelValue }`;buylinks.forEach(link=>{const url=new URL(link.href,window.location.origin);let tracker=url.searchParams.get(trackerParam)||'';if(!tracker.includes(funnelPair)){tracker+=tracker?`--${ funnelPair }`:funnelPair;url.searchParams.set(trackerParam,tracker);link.href=url.toString()}})}function setUrlParamsOnBuyLinks(){if(!urlParams.toString()){return}let keysToCopy=[];if(pageTypes.cartpanda){keysToCopy=Array.from(urlParams.keys())}else if(pageTypes.digistore24){if(urlParams.has('custom')){keysToCopy=['custom']}}else{if(urlParams.has('campaignkey')){keysToCopy=['campaignkey']}}if(!keysToCopy.length){return}buylinks.forEach(link=>{const url=new URL(link.href,window.location.origin);keysToCopy.forEach(key=>{url.searchParams.set(key,urlParams.get(key))});link.href=url.toString()})}function appendTrackerValueToParam(url,param,newValue){if(!url||!param||!newValue){return}let currentValue=url.searchParams.get(param);if(!currentValue){url.searchParams.set(param,newValue);return}const parts=currentValue.split('--');if(parts[0]===newValue){return}const filteredParts=parts.filter(p=>p!==newValue);filteredParts.unshift(newValue);url.searchParams.set(param,filteredParts.join('--'))}const legacyApplied=applyLegacyParamsToTracker();setUrlParamsOnBuyLinks();setFunnelIdOnBuyLinks();setKitOnBuylinks();if(!legacyApplied){renderKitSection()}if(isFrontBlack||hasCopyBlack){buylinks.forEach(link=>{const url=new URL(link.href,window.location.origin);appendTrackerValueToParam(url,trackerParam,'pg-cyb');link.href=url.toString()})}if(hasCopyBlack){showCopyBlack();bodyClassList.add('banner-hidden')}else{removeCopyBlack()}});
